-- ThreeK: live fixed-demo catalog, 20 hotels / 60 room types / 1084 managed units.
-- DATA ONLY: select your existing threek_booking database in phpMyAdmin before import.
-- Requires the current main schema/migrations. Back up first.
-- Hides ALL hotels outside this list; retains their IDs, rooms, bookings and accounts.
-- Insert-only on slug + room code: reruns never reset prices, stock, edits or booking history.
-- No fake reviews, provider IDs, photos, deposits or seasonal cancellation fees.
-- Capacity uses MAX ADULTS because this app has one total-guests field, not child ages.
SET NAMES utf8mb4;
START TRANSACTION;

INSERT INTO hotels (slug,name,city,type,stars,address,price_per_night,description,latitude,longitude,checkin_time,checkout_time,rules_json,is_active)
SELECT 'cicilia-rouge-dalat','CICILIA Rouge Dalat','dalat','hotel',4,'Số 15 Đường 3/4, Phường Xuân Hương (Phường 3 cũ), TP. Đà Lạt, Tỉnh Lâm Đồng',1100000,'Khách sạn có thiết kế hiện đại, không gian sang trọng và vị trí thuận tiện di chuyển đến khu vực trung tâm Đà Lạt.',11.9335,108.4412,'14:00:00','12:00:00','["Dữ liệu cố định dùng cho đồ án/demo; ảnh được bổ sung sau.", "Chỉ hủy đơn chờ/đã xác nhận trước ngày nhận phòng theo ngày lịch, không phải mốc đủ 24 giờ.", "Đơn đã thanh toán chỉ hủy được nếu có quyền hoàn hủy. Chính sách phí theo mùa và đặt cọc chưa áp dụng.", "Giới hạn đặt phòng trên demo tính theo số người lớn; thông tin trẻ em cần liên hệ để xác nhận.", "Liên hệ: 0263 3816 868"]',1
WHERE NOT EXISTS (SELECT 1 FROM hotels WHERE slug='cicilia-rouge-dalat');

