SELECT h.id,'standard','The Cosy Room',2,10,1100000,'Phòng có không gian ấm cúng, bố trí một giường Double. Demo: hủy trước ngày nhận phòng; đơn đã thanh toán chỉ hủy được khi có quyền hoàn hủy.',NULL,'1 giường Double (1.6m x 2m)',1,1,'["TV màn hình phẳng", "Tủ để đồ", "Phòng tắm riêng", "Máy sấy tóc", "Đồ dùng cá nhân", "Wi-Fi", "Đã bao gồm bữa sáng", "1 giường Double (1.6m x 2m)", "Giới hạn đặt trên demo: 2 người lớn/phòng."]',1 FROM hotels h WHERE h.slug='cicilia-rouge-dalat' AND NOT EXISTS (SELECT 1 FROM room_types r WHERE r.hotel_id=h.id AND r.code='standard');

